const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const houston = ee.Geometry.Point([-95.3698, 29.7604]);
    const aoi = houston.buffer(5000); // 5km buffer around the point
    const dateApril = ee.Date.fromYMD(2024, 4, 1);
    const dateMay = ee.Date.fromYMD(2024, 5, 1);

    // 2. Data Acquisition
    const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
        .select('avg_rad');

    const imageApril = collection.filterDate(dateApril, dateApril.advance(1, 'month')).first();
    const imageMay = collection.filterDate(dateMay, dateMay.advance(1, 'month')).first();

    // Check if images exist
    const aprilExists = imageApril.size().gt(0);
    const mayExists = imageMay.size().gt(0);

    if (!aprilExists.getInfo() || !mayExists.getInfo()) {
        console.log(`Data available for April 2024: ${aprilExists.getInfo()}`);
        console.log(`Data available for May 2024: ${mayExists.getInfo()}`);
        console.log('C1');
        return;
    }

    // 3. Processing & Calculation
    const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const statsApril = imageApril.reduceRegion({
        reducer: reducer,
        geometry: aoi,
        scale: 500, // VIIRS native resolution is ~500m
        maxPixels: 1e9
    });

    const statsMay = imageMay.reduceRegion({
        reducer: reducer,
        geometry: aoi,
        scale: 500,
        maxPixels: 1e9
    });

    // 4. Validation & Final Answer
    const aprilVal = statsApril.get('avg_rad').getInfo();
    const aprilCount = statsApril.get('avg_rad_count').getInfo();

    const mayVal = statsMay.get('avg_rad').getInfo();
    const mayCount = statsMay.get('avg_rad_count').getInfo();

    console.log(`April 2024 Brightness: ${aprilVal ? aprilVal.toFixed(2) : 'N/A'}, Pixel Count: ${aprilCount}`);
    console.log(`May 2024 Brightness: ${mayVal ? mayVal.toFixed(2) : 'N/A'}, Pixel Count: ${mayCount}`);

    if (aprilCount === 0 || mayCount === 0) {
        console.log('C2');
        return;
    }

    if (aprilVal === null || mayVal === null) {
        console.log('C3');
        return;
    }

    if (mayVal < aprilVal) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e.toString()}`);
    console.log('D');
});
